import{_ as p,r as s,o,c as l,e as n,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"{% partial %} - October CMS - 4.x","titleTemplate":false,"description":"Twig Tag","frontmatter":{"subtitle":"Twig Tag"},"headers":[{"level":2,"title":"Variables","slug":"variables","link":"#variables","children":[]},{"level":2,"title":"Passing Markup as a Variable","slug":"passing-markup-as-a-variable","link":"#passing-markup-as-a-variable","children":[{"level":3,"title":"Composable Partials","slug":"composable-partials","link":"#composable-partials","children":[]}]},{"level":2,"title":"Props and Attributes","slug":"props-and-attributes","link":"#props-and-attributes","children":[]},{"level":2,"title":"Setting Partial Contents to a Twig Variable","slug":"setting-partial-contents-to-a-twig-variable","link":"#setting-partial-contents-to-a-twig-variable","children":[]},{"level":2,"title":"Checking a Partial Exists","slug":"checking-a-partial-exists","link":"#checking-a-partial-exists","children":[]}],"relativePath":"4.x/markup/tag/partial.md","filePath":"4.x/markup/tag/partial.md"}'),u={name:"4.x/markup/tag/partial.md"};function r(g,a,k,d,m,w){const t=s("pre-heading"),e=s("post-heading");return o(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"{% partial %}",-1)),n(e),a[1]||(a[1]=i(`<p>The <code>{% partial %}</code> tag will parse a <a href="./../../cms/themes/partials.html">CMS partial</a> and render the partial contents on the page. To display a partial called <strong>footer.htm</strong>, simply pass the name after the <code>partial</code> tag quoted as a string.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>footer<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>A partial inside a subdirectory can be rendered in the same way.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar/menu<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p>The <a href="./../../cms/themes/themes.html">Themes documentation</a> has more details on subdirectory usage.</p></div><p>The partial name can also be a variable:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> tabName <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&quot;</span>profile<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> tabName <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="variables"><a href="#variables" class="header-anchor">#</a> Variables</h2><p>You can pass variables to partials by specifying them after the partial name:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>blog-posts<span class="token punctuation">&quot;</span></span> posts<span class="token operator">=</span>posts <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>You can also assign new variables for use in the partial:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>location<span class="token punctuation">&quot;</span></span> city<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Vancouver<span class="token punctuation">&quot;</span></span> country<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Canada<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Inside the partial, variables can be accessed like any other markup variable:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Country: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> country <span class="token delimiter punctuation">}}</span></span>, city: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> city <span class="token delimiter punctuation">}}</span></span>.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="passing-markup-as-a-variable"><a href="#passing-markup-as-a-variable" class="header-anchor">#</a> Passing Markup as a Variable</h2><p>It is possible to pass markup to a partial using the <code>body</code> attribute.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    This is the card contents
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The contents are then available as the <code>body</code> variable.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h3 id="composable-partials"><a href="#composable-partials" class="header-anchor">#</a> Composable Partials</h3><p>Composable partials are possible when combined with the <code>{% placeholder %}</code> <a href="./placeholder.html">Twig tag</a>. The following partial defines a <code>header</code> and a <code>body</code> section where HTML content can be added.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>header<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> header <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>body<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Next, you can include the <code>{% put %}</code> tag inside the <code>body</code> to compose the partial result with two HTML content sections.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> header <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>This is the card header<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This is the card contents<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="props-and-attributes"><a href="#props-and-attributes" class="header-anchor">#</a> Props and Attributes</h2><p>Partials can use the <code>{% props %}</code> tag to separate parameters into <strong>props</strong> (template variables) and <strong>attributes</strong> (HTML pass-through). This lets you build reusable partials with smart class merging and attribute forwarding.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token comment">{# partials/card.htm #}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">props</span> <span class="token punctuation">{</span>title<span class="token punctuation">:</span> <span class="token boolean">null</span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name"><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> attributes<span class="token punctuation">.</span>merge<span class="token punctuation">(</span><span class="token punctuation">{</span>class<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>card<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> title<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Hello<span class="token punctuation">&quot;</span></span> class<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>mt-4<span class="token punctuation">&quot;</span></span> id<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>featured<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Card content goes here<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The <code>title</code> parameter is a declared prop and becomes a template variable. The <code>class</code> and <code>id</code> parameters flow into the <code>attributes</code> bag. The <code>merge</code> method smart-appends the caller&#39;s class to the default.</p><div class="custom-block tip"><p>See the <a href="./props.html">Props Twig Tag</a> for the full <code>attributes</code> API and detailed usage examples.</p></div><h2 id="setting-partial-contents-to-a-twig-variable"><a href="#setting-partial-contents-to-a-twig-variable" class="header-anchor">#</a> Setting Partial Contents to a Twig Variable</h2><p>In any template you can set the partial contents to a variable with the <code>partial()</code> function. This lets you manipulate the output before display. Remember to use the <code>|raw</code> filter to prevent output escaping.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> cardPartial <span class="token operator">=</span> partial<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> cardPartial<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>You may also pass variables to the partial as the second argument.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> cardPartial <span class="token operator">=</span> partial<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> foo<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>bar<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="checking-a-partial-exists"><a href="#checking-a-partial-exists" class="header-anchor">#</a> Checking a Partial Exists</h2><p>The <code>hasPartial()</code> function can be used to check if a partial exists without rendering the contents, it will return true or false if the partial is found.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> hasPartial<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Card not found!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div>`,38))])}const v=p(u,[["render",r]]);export{b as __pageData,v as default};
